/* ************************************************************************* */
void
set_values (Eigen::MatrixXd&		A,
	    const Eigen::VectorXi&	Aidx,	    
	    const Eigen::VectorXd&	B,
	    const Eigen::VectorXi&	Bidx) {
  for (int n = 0; n < Aidx.size(); n++) A(Aidx(n)) = B(Bidx(n));
}

