std::vector<Eigen::VectorXcd>
solve (const Eigen::MatrixXd&	C) {
  Eigen::MatrixXd C0 = Eigen::MatrixXd::Zero(88, 88);
  Eigen::MatrixXd C1 = Eigen::MatrixXd::Zero(88, 27);
  setup_elimination_template (C, C0, C1);

  Eigen::VectorXi b_ind(7);
  b_ind << 81, 170, 259, 348, 437, 526, 615;
  Eigen::MatrixXd b = Eigen::MatrixXd::Zero(88, 7);
  for (int n = 0; n < b_ind.size(); n++) b(b_ind(n)) = -1;

  Eigen::MatrixXd alpha = (C0.transpose()).inverse() * b;
  Eigen::MatrixXd RR(34, 27);
  Eigen::MatrixXd E = Eigen::MatrixXd::Identity (27, 27);
  RR.block (0, 0, 7, 27) = alpha.transpose() * C1;
  RR.block (7, 0, 27, 27) = E;

  Eigen::MatrixXd AM(27, 27);
  Eigen::VectorXi AM_ind(27);
  AM_ind <<
    28,15,10,11,0,13,14,1,16,17,18,2,24,22,3,23,4,25,26,27,5,29,30,31,32,33,6;
  for (int n = 0; n < AM.rows(); n++) {
    AM.block (n, 0, 1, 27) = RR.block (AM_ind(n), 0, 1, 27);
  }

  Eigen::EigenSolver<Eigen::MatrixXd> es(AM);  
  Eigen::VectorXcd eval = es.eigenvalues();
  Eigen::MatrixXcd evec = es.eigenvectors();
  Eigen::VectorXcd tmp = es.eigenvectors().row(0);
  for (int n = 0; n < 27; n++) {
    for (int m = 0; m < 27; m++) {
      evec(n, m) /= tmp(m);
    }
  }
  std::vector<Eigen::VectorXcd> solution;
  Eigen::VectorXcd V1 = evec.row(1);
  Eigen::VectorXcd V2 = evec.row(12);  
  for (int n = 0; n < 27; n++) {
    Eigen::VectorXcd v(3);
    v << V1(n), V2(n), eval(n);
    solution.push_back (v);
  }
  return solution;
}

